// Production configuration is generated by the static build, never from browser input.
import { analyticsConfig } from './config.js';
const pages = new Set(['overview', 'bots', 'backtest', 'replay', 'orders', 'datasets', 'settings', 'privacy']);
const actions = new Set(['backtest_completed', 'csv_import_completed', 'replay_started', 'report_exported']);
let initialized = false;
export function track(name, page) {
  if (!analyticsConfig.enabled || !/^G-[A-Z0-9]+$/.test(analyticsConfig.measurementId) ||
      location.hostname === 'localhost' || location.hostname.endsWith('.localhost') || location.hostname.endsWith('.local') ||
      /^(?:\d{1,3}\.){3}\d{1,3}$/.test(location.hostname) || location.hostname.includes(':')) return;
  if (!(name === 'page_view' ? pages.has(page) : actions.has(name))) return;
  if (!initialized) {
    initialized = true;
    window.dataLayer = window.dataLayer || [];
    window.gtag = function () { window.dataLayer.push(arguments); };
    window.gtag('js', new Date());
    window.gtag('config', analyticsConfig.measurementId, {
      send_page_view: false, allow_google_signals: false, allow_ad_personalization_signals: false,
      page_location: `${location.origin}/demo`, page_referrer: '', ignore_referrer: true
    });
    const script = document.createElement('script');
    script.async = true; script.referrerPolicy = 'no-referrer';
    script.src = `https://www.googletagmanager.com/gtag/js?id=${analyticsConfig.measurementId}`;
    document.head.append(script);
  }
  window.gtag('event', name, {
    ...(name === 'page_view' ? { page_title: `TradeGrok ${page}`, page_location: `${location.origin}/demo/${page}`, page_referrer: '' } : {}),
    send_to: analyticsConfig.measurementId
  });
}
